  ('5062a227-9092-53d1-a878-26cf1d0a984c', '22222222-2222-2222-2222-222222222211', 'short', '算术平方根：非负数𝑎的算数平方根为√𝑎.', null, '', '', '数学/第1章 算术1  合订版.pdf', 3, true, 12, null),
  ('56c9cf49-f5e0-52e7-8c58-7ee7e94fae44', '22222222-2222-2222-2222-222222222211', 'short', '倒数：𝑎的倒数是 1 𝑎(𝑎≠0). 【注】 ①一个正数的平方根有两个,它们互为相反数；②0 的平方根仍为0； ③负数没有平方根；④𝒂𝟎= 𝟏(其中𝒂≠𝟎). 你的坚持，终将美好！ 3 题型1：考查有理数和无理数的性质', null, '', '', '数学/第1章 算术1  合订版.pdf', 3, true, 13, null),
  ('ca3bbb7a-2c69-550c-95b8-cad9f1808de4', '22222222-2222-2222-2222-222222222211', 'mcq', '若𝑥, 𝑦是有理数，且(1 + 2√3)𝑥+ (1 −√3)𝑦−2 + 5√3 = 0, 则𝑥, 𝑦的 值分别是( ).', '[{"key": "A", "text": "1,3"}, {"key": "B", "text": "−1,2"}, {"key": "C", "text": "−1,3"}, {"key": "D", "text": "1,2"}, {"key": "E", "text": "以上结论都不正确"}]'::jsonb, '', '', '数学/第1章 算术1  合订版.pdf', 4, true, 14, null),
  ('faa945aa-0886-5c7b-b042-7bd165fdf5d9', '22222222-2222-2222-2222-222222222211', 'mcq', '一个正数的两个平方根分别为2𝑎−1 和𝑎−2，则这个正数为( ).', '[{"key": "A", "text": "1"}, {"key": "B", "text": "4"}, {"key": "C", "text": "9"}, {"key": "D", "text": "16"}, {"key": "E", "text": "25"}]'::jsonb, '', '', '数学/第1章 算术1  合订版.pdf', 4, true, 15, null),
  ('1ca588a3-8c5d-5f98-9604-e9a1ac30ecbe', '22222222-2222-2222-2222-222222222211', 'mcq', '设𝑎与𝑏之和的倒数的2027 次方等于1，𝑎的相反数与𝑏之和的倒数的 2009 次方也等于1.则𝑎2007 + 𝑏2009 = ( ).', '[{"key": "A", "text": "−1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "1"}, {"key": "D", "text": "0"}, {"key": "E", "text": "−2"}]'::jsonb, '', '', '数学/第1章 算术1  合订版.pdf', 6, true, 16, null),
  ('bf2742fc-53f6-5456-a90e-001e1e5237ae', '22222222-2222-2222-2222-222222222211', 'mcq', '√5 + 2√6 −√3 = ( ).', '[{"key": "A", "text": "√2"}, {"key": "B", "text": "√3"}, {"key": "C", "text": "√6"}, {"key": "D", "text": "2√2"}, {"key": "E", "text": "2√3"}]'::jsonb, '', '', '数学/第1章 算术1  合订版.pdf', 6, true, 17, null),
