  ('aa35fdd8-b102-5d44-8ac6-245188be10ce', '22222222-2222-2222-2222-222222222211', 'short', '若𝑚= 𝑞 𝑝，其中𝑝与𝑞为非零整数，且𝑚3是一个整数.', null, '', '', '数学/第1章 算术1  合订版.pdf', 8, true, 19, null),
  ('887ebaeb-aa70-5eb5-9b28-adc1153bda5b', '22222222-2222-2222-2222-222222222211', 'short', '若𝑚= 𝑞 𝑝，其中𝑝与𝑞为非零整数，且 3𝑚+1 4 是一个整数. 思路点拨：考虑正难则反，反证法思想. 反证法的三步曲：', null, '', '', '数学/第1章 算术1  合订版.pdf', 8, true, 20, null),
