  ('1335d9ba-b01e-5149-a356-ae3639290e1e', '22222222-2222-2222-2222-222222222211', 'short', '奇数：不能被2 整除的整数叫奇数,如-5,-3,-1,1,3⋯.', null, '', '', '数学/第1章 算术1  合订版.pdf', 10, true, 25, null),
  ('7f94fc22-a422-5078-b685-bde395abbbac', '22222222-2222-2222-2222-222222222211', 'short', '偶数：能被2 整除的整数叫偶数,如-4,-2,0,2 ⋯ . 【注】整数可以按照奇数与偶数来分类，分类的标准是除以2 的余数， 若除以2 余1，则为奇数（故可以表示为2𝑘+1，其中𝑘是整数）； 若除以2 余0，则为偶数（故可以表示为2𝑘，其中𝑘是整数）.', null, '', '', '数学/第1章 算术1  合订版.pdf', 10, true, 26, null),
  ('3101e0f6-ea61-5bb8-9785-eeafabe742f7', '22222222-2222-2222-2222-222222222211', 'short', '运算性质（☆☆☆☆☆） 奇数±奇数=偶数 3 + 5 = 8 偶数±偶数=偶数 2 + 4 = 6 奇数±偶数=奇数 3 + 2 = 5 奇数×奇数=奇数 3 × 5 = 15 偶数×偶数=偶数 2 × 4 = 8 奇数×偶数=偶数 3 × 4 = 12 口诀：（核心功法，需要记住） 加同为偶，加不同为奇（减法运算与加法一致）； 乘偶为偶，不乘偶为奇 （对意多组数数的形也也成立）. 你的坚持，终将美好！ 10', null, '', '', '数学/第1章 算术1  合订版.pdf', 10, true, 27, null),
  ('61b210ab-0fcc-5b97-af66-4e31f0c1cfc4', '22222222-2222-2222-2222-222222222211', 'short', '常用结论', null, '', '', '数学/第1章 算术1  合订版.pdf', 11, true, 28, null),
  ('75eef78e-bbcd-5900-b3c6-f757511b774b', '22222222-2222-2222-2222-222222222211', 'short', '意多个偶数之和仍为偶数，奇数个奇数之和为奇数.', null, '', '', '数学/第1章 算术1  合订版.pdf', 11, true, 29, null),
  ('ec9bee4a-e2e3-5784-94f7-7a777a75cf6f', '22222222-2222-2222-2222-222222222211', 'short', '两个相邻整数必为一奇一偶且它们之和为奇数.', null, '', '', '数学/第1章 算术1  合订版.pdf', 11, true, 30, null),
  ('9ecec5ff-bf4c-5136-9253-39e823a177e9', '22222222-2222-2222-2222-222222222211', 'short', '如果𝑚, 𝑛是整数，则𝑚+ 𝑛和𝑚−𝑛的奇偶性相同.', null, '', '', '数学/第1章 算术1  合订版.pdf', 11, true, 31, null),
  ('668f1bb5-4483-55d8-9185-b5854ba6c5d6', '22222222-2222-2222-2222-222222222211', 'short', '两个自然数相加为奇数，这两个数必定一奇一偶，两个自然数相加是偶 数，这两个数必然同奇或同偶.', null, '', '', '数学/第1章 算术1  合订版.pdf', 11, true, 32, null),
  ('e9a18ec8-60ee-5dfd-8474-2401e13247e9', '22222222-2222-2222-2222-222222222211', 'short', '𝑎,𝑎2,𝑎3,⋯, 𝑎𝑛 （𝑎为整数，𝑛为正整数）的奇偶性相同. 题型1：考查奇偶性的判定', null, '', '', '数学/第1章 算术1  合订版.pdf', 11, true, 33, null),
  ('5297b1b3-515a-5678-a37c-776de5ef5e2a', '22222222-2222-2222-2222-222222222211', 'mcq', '若𝑛为意多自然数，则𝑛2 + 𝑛一定( ).', '[{"key": "A", "text": "为偶数"}, {"key": "B", "text": "为奇数"}, {"key": "C", "text": "与𝑛的奇偶性相同"}, {"key": "D", "text": "与𝑛的奇偶性不同"}, {"key": "E", "text": "无法判断"}]'::jsonb, '', '', '数学/第1章 算术1  合订版.pdf', 11, true, 34, null),
  ('a47bf4e9-8bc5-5222-835d-3466c4d75d60', '22222222-2222-2222-2222-222222222211', 'short', '已知𝑚, 𝑛为正整数，则𝑚为偶数.', null, '', '', '数学/第1章 算术1  合订版.pdf', 13, true, 35, null),
  ('c6d31d62-e5c4-54c8-83b0-e8545572c67a', '22222222-2222-2222-2222-222222222211', 'short', '3𝑚+ 2𝑛是偶数.', null, '', '', '数学/第1章 算术1  合订版.pdf', 13, true, 36, null),
