  ('e9b7f137-11a2-5809-a982-73289680ca6f', '22222222-2222-2222-2222-222222222211', 'short', '𝑚2 −𝑛2是4 的倍数. 平方差公式：𝒂𝟐−𝒃𝟐= (𝒂+ 𝒃)(𝒂−𝒃).', null, '', '', '数学/第1章 算术1  合订版.pdf', 13, true, 38, null),
  ('73ac24c0-ba0f-5a21-9299-dbb53c28c7c4', '22222222-2222-2222-2222-222222222211', 'short', '𝑚, 𝑛都是偶数.', null, '', '', '数学/第1章 算术1  合订版.pdf', 13, true, 39, null),
