  ('aabb7296-1c82-5861-82b9-f07e3702ba14', '22222222-2222-2222-2222-222222222211', 'short', '质数：一个大于1 的整数，除了1 和自身之外，不能被其它正整数整除 的数（也称素数）.', null, '', '', '数学/第1章 算术1  合订版.pdf', 16, true, 43, null),
  ('f6020285-afda-5df0-93da-4deadb48ee03', '22222222-2222-2222-2222-222222222211', 'short', '合数：一个大于1 的整数，除了能被1 和自身整除之外，还能被其它正 整数整除的数. 【注】①一个大于1 的正整数，不是质数就是合数；②最小的质数是2，且 2 也是唯一的偶质数；③最小的合数为4；④合数至少有3 个正因子 （也叫正约数）.', null, '', '', '数学/第1章 算术1  合订版.pdf', 16, true, 44, null),
  ('679b1b9b-2f75-5724-9125-e66fea0f9ad1', '22222222-2222-2222-2222-222222222211', 'short', '运算性质', null, '', '', '数学/第1章 算术1  合订版.pdf', 16, true, 45, null),
  ('4bdbcef4-5798-59ca-8d6c-c03a6234a4cd', '22222222-2222-2222-2222-222222222211', 'short', '若𝑎,𝑏为质数，且𝑎+𝑏=奇数，则𝑎,𝑏中必有一个是2.', null, '', '', '数学/第1章 算术1  合订版.pdf', 16, true, 46, null),
  ('c463a862-e991-5751-8818-fe962eca9fbd', '22222222-2222-2222-2222-222222222211', 'short', '若𝑎,𝑏,𝑐为质数，且𝑎+𝑏=𝑐，则𝑎,𝑏中必有一个是2.', null, '', '', '数学/第1章 算术1  合订版.pdf', 16, true, 47, null),
  ('021c3bd6-f865-5d0b-a9d2-54ff530c0f96', '22222222-2222-2222-2222-222222222211', 'short', '若𝑎,𝑏为质数，且𝑎−𝑏=1，则必有𝑎=3,𝑏=2. 你的坚持，终将美好！ 16', null, '', '', '数学/第1章 算术1  合订版.pdf', 16, true, 48, null),
