  ('920aa458-77d3-511b-917b-b731c549360a', '22222222-2222-2222-2222-222222222211', 'short', '（1）加同为偶，加不同为奇（减法运算与加法一致）；', null, '', '', '数学/第1章 算术2 合订版.pdf', 1, true, 57, null),
  ('b09d2c48-1ea3-5e50-8b2d-5b7f57c28486', '22222222-2222-2222-2222-222222222211', 'short', '乘偶为偶，不乘偶为奇（对任意多组数的情形也成立）.', null, '', '', '数学/第1章 算术2 合订版.pdf', 1, true, 58, null),
  ('462d9188-7e85-57eb-81e4-f1ebf6b95588', '22222222-2222-2222-2222-222222222211', 'short', '奇数可表示为2𝑘+1，𝑘∈𝒁；偶数可表示为2𝑘，𝑘∈𝒁.', null, '', '', '数学/第1章 算术2 合订版.pdf', 1, true, 59, null),
  ('f2e44ab4-7767-5ec3-8557-a003c72c7576', '22222222-2222-2222-2222-222222222211', 'short', '20 以内的质数：2,3,5,7,11,13,17,19（其中2 是唯一的偶质数） 知新 主讲人：十一老师 现在是网络设备测试时间，课程将准时开始，请大家耐心等待 你的坚持，终将美好！ 14 考点4：整除、余数、公倍数、公约数', null, '', '', '数学/第1章 算术2 合订版.pdf', 1, true, 60, null),
  ('9dc99fdd-5473-55bc-9c2f-19856fc5fb92', '22222222-2222-2222-2222-222222222211', 'short', '定义', null, '', '', '数学/第1章 算术2 合订版.pdf', 2, true, 61, null),
  ('e2df2548-a2cc-5392-a834-ed5d644218cf', '22222222-2222-2222-2222-222222222211', 'short', '整除：若整数𝑎除以非零整数𝑏，商为整数，且余数为零，则称𝑎能被𝑏整 除（或𝑏能整除𝑎），其中𝑎是𝑏的倍数，𝑏是𝑎的约数.如6÷2=3. 【注】A 除以B = A÷B；A 除B = B÷A；A 去除B = B÷A，牢牢记住 “被除数是需要被分割的数，除数是用来分割被除数的数”.', null, '', '', '数学/第1章 算术2 合订版.pdf', 2, true, 62, null),
  ('5e4af2b4-cc37-5ab6-882c-5a6b65631dae', '22222222-2222-2222-2222-222222222211', 'short', '余数：若整数𝑎 （被除数）除以整整数𝑏 （除数）时，在在唯一的𝑞 （商） 和𝑟（余数），满足𝑎= 𝑏𝑞+ 𝑟, 0 ⩽𝑟< 𝑏.这里的𝑟就叫做余数.', null, '', '', '数学/第1章 算术2 合订版.pdf', 2, true, 63, null),
  ('385ae356-3a25-59af-8880-178fc2bf1cde', '22222222-2222-2222-2222-222222222211', 'short', '公倍数：几个数公有的倍数叫公倍数，其中最小的叫最小公倍数. 如12，6，3，其中12 是它们的最小公倍数.', null, '', '', '数学/第1章 算术2 合订版.pdf', 2, true, 64, null),
  ('97145bf9-3f68-5c72-831b-45024e1016a2', '22222222-2222-2222-2222-222222222211', 'short', '公约数：几个数公有的约数叫公约数，其中最大的叫最大公约数. 如12，6，3，其中3 是它们的最大公约数.', null, '', '', '数学/第1章 算术2 合订版.pdf', 2, true, 65, null),
  ('fe5f1f15-040c-57f3-a612-9ef16744ac79', '22222222-2222-2222-2222-222222222211', 'short', '互质数：公约数只有1 的两个数称为互质数，如4 和9. 【注】整整数𝑎与𝑏的乘积等于这两个数的最小公倍数与最大公约数的乘积. 例如：12 和15（12=2×2×3=𝟐𝟐× 𝟑𝟏，15=𝟑𝟏×𝟓𝟏） 最小公倍数：取所有质因数次方最大的相乘起来，𝟐𝟐× 𝟑𝟏×𝟓𝟏= 𝟔𝟎 最大公约数：取公共质因数次方最小的相乘起来，𝟑𝟏= 𝟑 12×15=180 , 3×60=180. 你的坚持，终将美好！ 15', null, '', '', '数学/第1章 算术2 合订版.pdf', 2, true, 66, null),
  ('afb1f6dd-c071-53d0-a5c8-4a6a5fef999b', '22222222-2222-2222-2222-222222222211', 'short', '运算性质 如果𝑎,𝑏能被𝑐整除，则他们的和差也能被𝑐整除. 如 12 2 = 6， 8 2 = 4， 12+8 2 = 10， 12−8 2 = 2.', null, '', '', '数学/第1章 算术2 合订版.pdf', 3, true, 67, null),
  ('44b3267d-51df-51c5-a0a5-1fee6e56437f', '22222222-2222-2222-2222-222222222211', 'short', '常见数字整除特征', null, '', '', '数学/第1章 算术2 合订版.pdf', 3, true, 68, null),
  ('3d8c3cb6-f105-5f94-869b-0201905264ad', '22222222-2222-2222-2222-222222222211', 'short', '能被2 整除的数：个位上的数能被2 整除（偶数都能被2 整除），个位 数字为0,2,4,6,8.', null, '', '', '数学/第1章 算术2 合订版.pdf', 3, true, 69, null),
  ('ce4a8817-355c-53b9-9d2d-0f68a635d0df', '22222222-2222-2222-2222-222222222211', 'short', '能被4 整除的数：末两位（十位和个位）组成的两位数能被4 整除. 如12312', null, '', '', '数学/第1章 算术2 合订版.pdf', 3, true, 70, null),
  ('79822a41-a14a-5bbb-96a2-f2e5945a3dbf', '22222222-2222-2222-2222-222222222211', 'short', '能被8 整除的数：末三位（百、十和个位）组成的三位数能被8 整除. 如123160，123064 【注】能被𝟐𝒌整除的数，它的末𝒌位组成的数字能够被𝟐𝒌整除.', null, '', '', '数学/第1章 算术2 合订版.pdf', 3, true, 71, null),
  ('799d8fc3-a8c7-5d03-b497-9c7e25437e56', '22222222-2222-2222-2222-222222222211', 'short', '能被3 整除的数：各位数字之和能被3 整除. 如192', null, '', '', '数学/第1章 算术2 合订版.pdf', 3, true, 72, null),
  ('81470a40-64de-5197-b34f-02dece48b05b', '22222222-2222-2222-2222-222222222211', 'short', '能被9 整除的数：各位数字之和能被9 整除. 如198', null, '', '', '数学/第1章 算术2 合订版.pdf', 3, true, 73, null),
  ('ec15ff29-bbe8-5f48-9b91-90be7ece050c', '22222222-2222-2222-2222-222222222211', 'short', '能被5 整除的数：个位数字为0 或5. 如55,50', null, '', '', '数学/第1章 算术2 合订版.pdf', 3, true, 74, null),
  ('1720e793-2418-57ae-aaea-d9bc8e74e1c8', '22222222-2222-2222-2222-222222222211', 'short', '能被6 整除的数：同时满足能被2 和3 整除. 如24', null, '', '', '数学/第1章 算术2 合订版.pdf', 3, true, 75, null),
  ('45628783-ab13-510f-9915-76852a5902b3', '22222222-2222-2222-2222-222222222211', 'mcq', '能被10 整除的数：个位数字为0. 你的坚持，终将美好！ 16 题型1：考查整除的性质 要求判断每题给出的条件（1）和（2）能否充分支持题干所陈述的结论．以下五个选项为 判断结果，请选择一项符合试题要求的判断。', '[{"key": "A", "text": "条件（1）充分，但条件（2）不充分"}, {"key": "B", "text": "条件（2）充分，但条件（1）不充分"}, {"key": "C", "text": "条件（1）和（2）单独都不充分，但条件（1）和条件（2）联合起来充分"}, {"key": "D", "text": "条件（1）充分，条件（2）也充分"}, {"key": "E", "text": "条件（1）和条件（2）单独都不充分，条件（1）和条件（2）联合起来也不充分"}]'::jsonb, '', '', '数学/第1章 算术2 合订版.pdf', 3, true, 76, null),
  ('c0f29efd-9205-5926-a964-9f82b54366dc', '22222222-2222-2222-2222-222222222211', 'short', '3𝑛 14 是个整数.', null, '', '', '数学/第1章 算术2 合订版.pdf', 4, true, 77, null),
  ('19b64f62-4c0a-5568-acb2-08f8968ead72', '22222222-2222-2222-2222-222222222211', 'short', '𝑛是一个整数，且 𝑛 14 也是一个整数.', null, '', '', '数学/第1章 算术2 合订版.pdf', 4, true, 78, null),
  ('95fb9751-e32e-57b8-8e01-b81ca7c8a366', '22222222-2222-2222-2222-222222222211', 'short', '𝑛是一个整数，且 𝑛 7 也是一个整数. 思路点拨：寻找反例满足的要素', null, '', '', '数学/第1章 算术2 合订版.pdf', 4, true, 79, null),
  ('2fca6604-8492-5207-b6a5-d7611d423423', '22222222-2222-2222-2222-222222222211', 'short', '符合条件；（2）与结果矛盾；（3）简单好算. 你的坚持，终将美好！ 17 你的坚持，终将美好！ 18', null, '', '', '数学/第1章 算术2 合订版.pdf', 4, true, 80, null),
  ('edc07af3-86fa-5f25-ba4a-39b1fab61d58', '22222222-2222-2222-2222-222222222211', 'mcq', '不超过100 的整整数，能被7 或5 整除的有( )个.', '[{"key": "A", "text": "35"}, {"key": "B", "text": "34"}, {"key": "C", "text": "32"}, {"key": "D", "text": "37"}, {"key": "E", "text": "40"}]'::jsonb, '', '', '数学/第1章 算术2 合订版.pdf', 6, true, 81, null),
  ('ecdd8374-7f3d-5fd5-ac1a-615634e734c2', '22222222-2222-2222-2222-222222222211', 'mcq', '设𝑝是整奇数，则𝑝2除以8 的余数等于( ).', '[{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "3"}, {"key": "D", "text": "4"}, {"key": "E", "text": "5"}]'::jsonb, '', '', '数学/第1章 算术2 合订版.pdf', 6, true, 82, null),
  ('29debd8d-2d02-5c10-84e4-6595c493173f', '22222222-2222-2222-2222-222222222211', 'mcq', '12、18、24 的最大公约数和最小公倍数是( ).', '[{"key": "A", "text": "2,36"}, {"key": "B", "text": "6,72"}, {"key": "C", "text": "3,24"}, {"key": "D", "text": "6,104"}, {"key": "E", "text": "3,48"}]'::jsonb, '', '', '数学/第1章 算术2 合订版.pdf', 8, true, 83, null),
  ('a9784f25-a4e3-57c5-bca0-996b393bc109', '22222222-2222-2222-2222-222222222211', 'mcq', '将长、宽、高分别为12、9、6 的长方体切割成小整方体，且切割后 无剩余，能切割成相同的整方体的最小个数为( ).', '[{"key": "A", "text": "3"}, {"key": "B", "text": "6"}, {"key": "C", "text": "24"}, {"key": "D", "text": "96"}, {"key": "E", "text": "648"}]'::jsonb, '', '', '数学/第1章 算术2 合订版.pdf', 8, true, 84, null),
  ('410d6573-1619-5ee5-ab6a-4e46294fa87e', '22222222-2222-2222-2222-222222222211', 'mcq', '两个整整数甲数和乙数的最大公约数是6，最小公倍数是90.如果甲 数是18，那么乙数是𝑚，则𝑚的各个数位之和为多少( ).', '[{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5"}, {"key": "E", "text": "6"}]'::jsonb, '', '', '数学/第1章 算术2 合订版.pdf', 10, true, 85, null),
  ('785d3f46-1179-5884-9abc-758f10665755', '22222222-2222-2222-2222-222222222211', 'short', '定义', null, '', '', '数学/第1章 算术2 合订版.pdf', 11, true, 86, null),
  ('56140d16-2eb6-58ff-80e7-8cae57b832b7', '22222222-2222-2222-2222-222222222211', 'short', '比：两个数相除，又称为这两个数的比.即𝑎: 𝑏= 𝑎 𝑏其中𝑎叫做比的前 项，𝑏叫做比的后项.相除所得的商叫做比值.记作 𝑎: 𝑏= 𝑎 𝑏= 𝑘.', null, '', '', '数学/第1章 算术2 合订版.pdf', 11, true, 87, null),
  ('66708b27-512d-5a55-be0a-85acdd34492f', '22222222-2222-2222-2222-222222222211', 'short', '比例：相等的比称为比例，记作𝑎: 𝑏= 𝑐: 𝑑或 𝑎 𝑏= 𝑐 𝑑.', null, '', '', '数学/第1章 算术2 合订版.pdf', 11, true, 88, null),
  ('a4f0305a-714e-5060-a51d-f69e7ca88b71', '22222222-2222-2222-2222-222222222211', 'short', '若𝑦= 𝑘𝑥（𝑘≠0）,则称𝑦与𝑥成整比, 𝑘称为比例系数. 本质是𝑦与𝑥的比 值为定值.', null, '', '', '数学/第1章 算术2 合订版.pdf', 11, true, 89, null),
  ('80ad4f4c-85a8-5d66-8e1e-0a43d6875afe', '22222222-2222-2222-2222-222222222211', 'short', '若𝑦= 𝑘 𝑥（𝑘≠0） ,则称𝑦 与𝑥 成反比, 𝑘 称为比例系数. 本质是𝑦 与𝑥的 乘 积为定值.', null, '', '', '数学/第1章 算术2 合订版.pdf', 11, true, 90, null),
  ('2dc36f8d-b216-5882-9e4b-c03a73a69b0f', '22222222-2222-2222-2222-222222222211', 'short', '性质', null, '', '', '数学/第1章 算术2 合订版.pdf', 11, true, 91, null)
